        {
            MessageBuffer buffer = CopyMessage(ref request);

            WriteMessageToLog(buffer, RequestPrefix);

            return null;
        }

        private MessageBuffer CopyMessage(ref Message request)
        {
            XmlDocument doc = new XmlDocument();
            MemoryStream ms = new MemoryStream();
            XmlWriter writer = XmlWriter.Create(ms);
            request.WriteMessage(writer);
            writer.Flush();
            ms.Position = 0;
            doc.Load(ms);

            XmlDocument convertedDocument = ChangeMessage(doc);

            var stream = new System.IO.MemoryStream();
            var streamWriter = new System.IO.StreamWriter(stream);
            streamWriter.Write(convertedDocument.OuterXml);
            streamWriter.Flush();
            stream.Position = 0;
            var output = XmlReader.Create(stream);

            request = Message.CreateMessage(output, int.MaxValue, request.Version);

            MessageBuffer buffer = request.CreateBufferedCopy(Int32.MaxValue);
            request = buffer.CreateMessage();
            return buffer;
        }

