                StringBuilder sb = new StringBuilder();
                using (System.Xml.XmlWriter xw = System.Xml.XmlWriter.Create(sb))
                {
                    Message message = buffer.CreateMessage();
                    message.WriteMessage(xw);
                    xw.Close();
                }

