                //element.SetAttribute("xmlns:xsi", "http://www.w3.org/2001/XMLSchema-instance");
            }

            XmlElement detailTag = (XmlElement)doc.GetElementsByTagName("BAPI_ALM_ORDER_GET_DETAIL").Item(0);
            if (detailTag != null)
            {
                detailTag.Prefix = "urn";
            }

            return doc;
        }
        #endregion
    }

    /// <summary>
    /// define customer message inspector
    /// </summary>
    public class HttpHeaderMessageInspector : IClientMessageInspector
    {
        private readonly Dictionary<string, string> _headers;
        public string LastRequestXml { get; private set; }
        public string LastResponseXml { get; private set; }

        public HttpHeaderMessageInspector(Dictionary<string, string> headers)
        {
            _headers = headers;
        }

        public void AfterReceiveReply(ref Message reply, object correlationState)
        {

        }

        public object BeforeSendRequest(ref Message request, IClientChannel channel)
        {

            if (request.Properties.Count == 0 || request.Properties[HttpRequestMessageProperty.Name] == null)
            {
                request.Properties.Add(HttpRequestMessageProperty.Name, new HttpRequestMessageProperty());
            }
            var headersCollection = ((HttpRequestMessageProperty)request.Properties[HttpRequestMessageProperty.Name]).Headers;

            foreach (var header in _headers) headersCollection[header.Key] = header.Value;

            return null;
        }
    }
}
